# DK SBT.  Sønderborg - Tønder
#
let st = path("d3.dk.sbt");

with detail = 3, railway = :first :cat:ac25 :pax {
    with link = "point.dk.Sønderborg", railway = :station {
        track(st[:son.a, :son + 0.5sw]);
        marker(:right :de.bf, st[:son] >> 0.5mt);
        slabel(:right :bold, st[:son] >> 0.5mt >> 1sh + (-2.8dt, -1.2dt),
            "Sønderborg"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:son + 0.49sw, :son + 1.71km]);
        line_label(:left:ne, st[:son + 1.7km] << 0.5mt, "SBT");
        track(st[:son + 1.69km, :rag - 0.49sw]);
    }

    with link = "point.dk.Ragebøl", railway = :station {
        track(st[:rag - 0.5sw, :rag + 0.5sw]);
        marker(:right :de.hp :removed, st[:rag] >> 0.5mt);
        marker(:right :de.exbf :removed, st[:rag] >> 0.5mt);
        slabel(:right :removed, st[:rag] >> 0.5mt >> 1.4sh + (1.3dt, 0.5dt),
            "Ragebøl"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:rag + 0.49sw, :vso.ys - 0.49seg]);
    }

    with link = "point.dk.Vester-Sottrup", railway = :station {
        track(:removed,
                st[:vso.ys, :vso + 0.5sw] << 1ms << 1mt
            --  st[:vso + 0.5sw + 1dl, :vso + 0.5sw + 1.1dl]
        );
        track(st[:vso.ys - 0.5seg, :vso + 0.5sw + 2dl]);
        marker(:right :de.hp :removed, st[:vso] >> 0.5mt);
        marker(:right :de.exbf :removed, st[:vso] >> 0.5mt);
        slabel(:right :bold :removed,
            st[:vso] >> 0.5mt >> 1.4sh + (1.4dt, 0.3dt),
            "Vester Sottrup"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:vso + 0.49sw + 2dl, :avn - 0.49sw]);
    }

    with link = "point.dk.Avnbøl", railway = :station {
        track(st[:avn - 0.5sw, :avn + 0.5sw]);
        marker(:left :de.hp :removed, st[:avn] << 0.5mt);
        marker(:left :de.exbf :removed, st[:avn] << 0.5mt);
        slabel(:top :removed, st[:avn] >> 0.5mt >> 0.6dt,
            "Avnbøl"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:avn + 0.49sw, :avn + 1.81km]);
        line_label(:left:nw, st[:avn + 1.8km] << 0.5mt, "SBT");
        track(st[:avn + 1.79km, :ads - 0.49sw]);
    }

    with link = "point.dk.Adsbøl", railway = :station {
        track(st[:ads - 0.5sw, :ads + 0.5sw]);
        marker(:left :de.hp :removed, st[:ads] << 0.5mt);
        slabel(:right :removed, st[:ads] << 0.5mt << 1sh + (1.1dt, 1.2dt),
            "Adsbøl"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:ads + 0.49sw, :gra.ya - 0.49seg]);
        track(:ror, st[:gra.ya - 0.5seg, :gra.ya]);
        track(:ror, st[:gra.ya, :gra - 0.49sw]);
    }

    with link = "point.dk.Gråsten", railway = :station {
        track(st[:gra - 0.5sw, :gra + 0.5sw]);
        track(:removed :g1000, st[:gra - 0.5sw, :gra + 0.5sw] >> 1ms >> 1mt);
        marker(:right :de.bf, st[:gra] >> 1ms >> 1.5mt);
        slabel(:left :bold, st[:gra] >> 1ms >> 1.5mt >> 1sh + (-1.4dt, 0.6dt),
            "Gråsten"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:gra + 0.49sw, :rin - 0.49sw]);
    }

    with link = "point.dk.Rinkenæs", railway = :station {
        track(st[:rin - 0.5sw, :rin + 0.5sw]);
        marker(:left :de.hp :removed, st[:rin] << 0.5mt);
        marker(:left :de.exbf :removed, st[:rin] << 0.5mt);
        slabel(:right :removed, st[:rin] << 0.5mt << 1.4sh + (1.5dt, 1.7dt),
            "Rinkenæs"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:rin + 0.49sw, :rin + 1.61km]);
        line_label(:left:n, st[:rin + 1.6km] << 0.5mt, (-0.5dt, 0dt), "SBT");
        track(st[:rin + 1.59km, :tor - 0.49sw]);
    }

    with link = "point.dk.Tørsbøl", railway = :station {
        track(:removed,
                st[:tor + 0.49sw + 0.5dl, :tor + 0.5sw + 0.5dl]
            --  st[:tor + 0.5sw + 1.5dl, :tor.yp] << 1ms << 1mt
        );
        track(st[:tor - 0.5sw, :tor.yp + 0.5seg]);
        marker(:left :de.hp :removed, st[:tor] << 0.5mt);
        marker(:left :de.exbf :removed, st[:tor] << 0.5mt);
        slabel(:bottom :bold :removed,
            st[:tor] << 0.5mt << 1.4sh + (-1.5dt, 0.8dt),
            "Tørsbøl"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:tor.yp + 0.49seg, :tor.yp + 1.71km]);
        line_label(:right:sw, st[:tor.yp + 1.7km] >> 0.5mt, "SBT");
        track(st[:tor.yp + 1.69km, :lun - 0.49sw]);
    }

    with link = "point.dk.Lundtoft", railway = :station {
        track(st[:lun - 0.5sw, :lun + 0.5sw]);
        marker(:left :de.hp :removed, st[:lun] << 0.5mt);
        slabel(:bottom :removed, st[:lun] << 0.5mt << 1sh + (-2dt, 0.4dt),
            "Lundtoft"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:lun + 0.49sw, :kli - 0.49sw]);
    }

    with link = "point.dk.Kliplev", railway = :station {
        track(st[:kli - 0.5sw, :kli + 0.5sw]);
        marker(:right :de.hp, st[:kli] >> 0.5mt);
        slabel(:top, st[:kli] >> 0.5mt >> 1sh >> 0.4dt,
            "Kliplev"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:kli + 0.49sw, :bje - 0.49sw]);
    }

    with link = "point.dk.Bjerndrup", railway = :station {
        track(st[:bje - 0.5sw, :bje + 0.5sw]);
        marker(:right :de.hp :removed, st[:bje] >> 0.5mt);
        slabel(:top :removed, st[:bje] >> 0.5mt >> 1sh >> 0.2dt,
            "Bjerndrup"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:bje + 0.49sw, :bje + 2.21km]);
        line_label(:left:n, st[:bje + 2.2km] << 0.5mt, "SBT");
        track(st[:bje + 2.19km, :tin.xs - 1mt]);
        track(:lor,
                st[:tin.xs - 1.1mt, :tin.xs - 1mt]
            ..  st[:tin.ys, :tin.ys + 0.1dl] >> 0.5md >> 1ms >> 0.5mt
        );
    }
}

with detail = 3, railway = :first :expax :suspended {
    with link = "line.dk.SBT" {
        track(:station,
                st[:tin.yt - 0.1dl, :tin.yt] << 0.5md << 1ms << 0.5mt
            ..  st[:tin.xt + 1md, :tin.xt + 1.1md]
        );
        track(st[:tin.xt + 1md, :tin.xt + 1.51km]);
        line_label(:right:s, st[:tin.xt + 1.5km] >> 0.5mt, "SBT");
        track(st[:tin.xt + 1.49km, :ter - 0.49sw]);
    }

    with link = "point.dk.Terkelsbøl", railway = :station {
        track(st[:ter - 0.5sw, :ter + 0.5sw]);
        marker(:left :de.hp, st[:ter] << 0.5mt);
        marker(:left :de.exbf, st[:ter] << 0.5mt);
        slabel(:bottom, st[:ter] << 0.5mt << 1.4sh << 0.3dt,
            "Terkelsbøl"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:ter + 0.49sw, :byl - 0.49sw]);
    }

    with link = "point.dk.Bylderup-Bov", railway = :station {
        track(st[:byl - 0.5sw, :byl + 0.5sw]);
        marker(:left :de.bf, st[:byl] << 0.5mt);
        slabel(:bottom, st[:byl] << 0.5mt << 1sh << 0.2dt,
            "Bylderup-Bov"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:byl + 0.49sw, :byl + 3.91km]);
        line_label(:right:s, st[:byl + 3.9km] >> 0.5mt, "SBT");
        track(st[:byl + 3.89km, :jej - 0.49sw]);
    }

    with link = "point.dk.Jejsing", railway = :station {
        track(st[:jej - 0.5sw, :jej + 0.5sw]);
        marker(:left :de.hp, st[:jej] << 0.5mt);
        marker(:left :de.exbf, st[:jej] << 0.5mt);
        slabel(:bottom, st[:jej] << 0.5mt << 1.4sh << 0.3dt,
            "Jejsing"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:jej + 0.49sw, :ror - 0.49sw]);
    }

    with link = "point.dk.Rørkær", railway = :station {
        track(st[:ror - 0.5sw, :ror + 0.5sw]);
        marker(:left :de.hp :removed, st[:ror] << 0.5mt);
        slabel(:top :removed, st[:ror] >> 0.5mt >> 0.3dt,
            "Rørkær"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:ror + 0.49sw, :ror + 2.01km]);
        line_label(:right:s, st[:ror + 2km] >> 0.5mt, "SBT");
        track(st[:ror + 1.99km, :too - 0.49sw]);
    }

    with link = "point.dk.Tønder-Øst", railway = :station {
        track(st[:too - 0.5sw, :too + 0.5sw]);
        marker(:left :de.bf, st[:too] << 0.5mt);
        slabel(:right, st[:too - 0.5sw] << 0.5mt << 1sh + (0.8dt, 1.3dt),
            "Tønder Øst*"
        );
    }

    with link = "line.dk.SBT" {
        track(:ror,
                st[:too + 0.49sw, :ton.xt]
            ..  st[:ton.yt, :ton.yt + 0.1dl] << 1mt << 1ms
        );
    }

    # point.dk.Tønder  dk.BTR
}

